class Solution {
public:
    vector<string> restoreIpAddresses(string s) {
        vector<string> result;
        int n = s.size();
        if (n < 4 || n > 12) return result;
        string current;
        backtrack(s, 0, 0, current, result);
        return result;
    }

private:
    void backtrack(const string& s, int start, int segment, string& current, vector<string>& result) {
        if (segment == 4) {
            if (start == (int)s.size()) {
                current.pop_back();
                result.push_back(current);
                current.push_back('.');
            }
            return;
        }
        int n = s.size();
        for (int len = 1; len <= 3 && start + len <= n; len++) {
            if (isValid(s, start, len)) {
                current.append(s, start, len);
                current.push_back('.');
                backtrack(s, start + len, segment + 1, current, result);
                current.pop_back();
                for (int i = 0; i < len; i++) current.pop_back();
            }
        }
    }

    bool isValid(const string& s, int start, int len) {
        if (len > 1 && s[start] == '0') return false;
        int val = 0;
        for (int i = 0; i < len; i++) {
            val = val * 10 + (s[start + i] - '0');
        }
        return val <= 255;
    }
};
